/bin/bash -c "python3 - <<'PY'
from fractions import Fraction
from math import comb

def sign(v):
    return (v>0)-(v<0)

def candidates(xs,ys):
    rows=[]
    for sense in [1,-1]:
        for pivot in xs:
            if pivot == 0:
                continue
            w=(Fraction(-sense),Fraction(sense)/pivot)
            values=[w[0]+w[1]*x for x in xs]
            exact_labels=[sign(v) for v in values]
            labels=[0 if abs(v)<Fraction(1,100000000) else sign(v) for v in values]
            paper_loss=sum(a"'!=b for a,b in zip(labels,ys) if a!=0 and b!=0)
            eq1_loss=sum(a!=b for a,b in zip(exact_labels,ys))
            rows.append((paper_loss,eq1_loss,w,labels))
    return min(rows,key=lambda row:row[0])

for xs,ys in [([Fraction(1),Fraction(2)],[-1,1]),([Fraction(1),Fraction(1)+Fraction(1,10**9),Fraction(1)+Fraction(2,10**9)],[1,-1,1])]:
    thresholds=[xs[0]-1]+[(a+b)/2 for a,b in zip(xs,xs[1:])]+[xs[-1]+1]
    optimum=min(sum(sign(sense*(x-t))!=y for x,y in zip(xs,ys)) for t in thresholds for sense in [-1,1])
    print({'"'x':list(map(str,xs)),'labels':ys,'best_paper_candidate':str(candidates(xs,ys)),'true_optimum':optimum})

print('No-pruning model updates after a size-D combination is completed:')
for d in [1,2,3]:
    for n in [10,20,40]:
        updates=sum(comb(k-1,d-1)*(n-k) for k in range(d,n+1))
        assert updates==comb(n,d+1)
        print({'N':n,'D':d,'updates':updates,'C(N,D+1)':comb(n,d+1)})
